# Review package: 602a2eef977c2722deddf3c0c7ed8cfa69ebd618..48f0207

## Commits
48f0207 Add greeting function with custom formatting support

## Files changed
 greet.js      | 25 +++++++++++++++++++++++++
 greet.test.js | 48 ++++++++++++++++++++++++++++++++++++++++++++++++
 2 files changed, 73 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..b2af3a5
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,25 @@
+/**
+ * Greet a person by name with optional custom formatting.
+ *
+ * @param {string} name - The name to greet. Empty/invalid names default to "Guest".
+ * @param {Object} options - Optional formatting options.
+ * @param {string} options.greeting - Custom greeting word (default: "Hello").
+ * @param {string} options.punctuation - Custom punctuation (default: "!").
+ * @returns {string} A formatted greeting string.
+ *
+ * Examples:
+ *   greet("Alice") => "Hello, Alice!"
+ *   greet("Bob", { greeting: "Hi" }) => "Hi, Bob!"
+ *   greet("", { greeting: "Hey" }) => "Hey, Guest!"
+ */
+function greet(name, options = {}) {
+  const greeting = options.greeting || 'Hello';
+  const punctuation = options.punctuation || '!';
+
+  // Handle empty, null, undefined, non-string, or whitespace-only names
+  const validName = (typeof name === 'string' && name.trim()) ? name : 'Guest';
+
+  return `${greeting}, ${validName}${punctuation}`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..eed98d3
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,48 @@
+const { test } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for valid name', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet with custom greeting word', () => {
+  const result = greet('Bob', { greeting: 'Hi' });
+  assert.strictEqual(result, 'Hi, Bob!');
+});
+
+test('greet with custom punctuation', () => {
+  const result = greet('Charlie', { punctuation: '.' });
+  assert.strictEqual(result, 'Hello, Charlie.');
+});
+
+test('greet with both custom greeting and punctuation', () => {
+  const result = greet('Diana', { greeting: 'Hey', punctuation: '!!' });
+  assert.strictEqual(result, 'Hey, Diana!!');
+});
+
+test('greet handles empty string name gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet handles undefined name gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet handles null name gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet handles non-string name gracefully', () => {
+  const result = greet(123);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet with whitespace-only name treated as empty', () => {
+  const result = greet('   ');
+  assert.strictEqual(result, 'Hello, Guest!');
+});
